<?php
namespace App\Domain\Statistics; use App\Domain\PublicChrome\PublicLink; use App\Models\Statistic; use Illuminate\Support\Facades\Cache; use Throwable; final class StatisticViewData { public function published():array{try{return Cache::remember('public.statistics.v1.'.StatisticCache::version().'.'.now()->format('YmdHi'),now()->addMinutes(10),fn()=>$this->load());}catch(Throwable){return $this->load();}} public function preview(Statistic $item):array{return $this->transform($item);} private function load():array{return Statistic::publiclyVisible()->orderByDesc('is_featured')->orderBy('display_order')->limit(100)->get()->map(fn($x)=>$this->transform($x))->all();} private function transform(Statistic $x):array{return ['label'=>$x->label,'value'=>$x->value,'prefix'=>$x->prefix,'suffix'=>$x->suffix,'displayed_value'=>(string)$x->prefix.(string)$x->value.(string)$x->suffix,'description'=>$x->description,'group'=>$x->statistic_group,'icon'=>$x->icon,'source_note'=>$x->source_note,'source_url'=>PublicLink::isSafeUrl($x->source_url)?$x->source_url:null,'as_of_date'=>$x->as_of_date?->toDateString()];} }
